import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport '../../announcements/providers/announcement_providers.dart';\nimport '../../../core/providers/core_providers.dart';\nimport 'package:intl/intl.dart';\n\nclass ManageCommentsScreen extends ConsumerWidget {\n  const ManageCommentsScreen({Key? key}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final schoolId = 'dummy_school_id';\n    final announcementsAsync = ref.watch(announcementsProvider(schoolId));\n\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('إدارة التعليقات'),\n        centerTitle: true,\n      ),\n      body: announcementsAsync.when(\n        data: (announcements) {\n          if (announcements.isEmpty) {\n            return const Center(child: Text('لا توجد إعلانات لعرض تعليقاتها.'));\n          }\n          return ListView.builder(\n            itemCount: announcements.length,\n            itemBuilder: (context, index) {\n              final ann = announcements[index];\n              return ExpansionTile(\n                title: Text(ann.title, style: const TextStyle(fontWeight: FontWeight.bold)),\n                subtitle: Text(DateFormat('yyyy-MM-dd').format(ann.createdAt)),\n                children: [\n                  Consumer(\n                    builder: (context, ref, child) {\n                      final commentsAsync = ref.watch(commentsProvider(ann.id));\n                      return commentsAsync.when(\n                        data: (comments) {\n                          if (comments.isEmpty) {\n                            return const Padding(\n                              padding: EdgeInsets.all(16.0),\n                              child: Text('لا توجد تعليقات على هذا الإعلان.'),\n                            );\n                          }\n                          return ListView.builder(\n                            shrinkWrap: true,\n                            physics: const NeverScrollableScrollPhysics(),\n                            itemCount: comments.length,\n                            itemBuilder: (context, cIndex) {\n                              final comment = comments[cIndex];\n                              return ListTile(\n                                leading: const Icon(Icons.person),\n                                title: Text(comment.senderName, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 14)),\n                                subtitle: Text(comment.content),\n                                trailing: IconButton(\n                                  icon: const Icon(Icons.delete, color: Colors.red),\n                                  onPressed: () async {\n                                    final confirm = await showDialog<bool>(\n                                      context: context,\n                                      builder: (ctx) => AlertDialog(\n                                        title: const Text('حذف التعليق'),\n                                        content: const Text('هل أنت متأكد من حذف هذا التعليق؟'),\n                                        actions: [\n                                          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('إلغاء')),\n                                          TextButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('حذف', style: TextStyle(color: Colors.red))),\n                                        ],\n                                      )\n                                    );\n                                    if (confirm == true) {\n                                      try {\n                                        await ref.read(announcementServiceProvider).deleteComment(comment.id);\n                                        if (context.mounted) {\n                                          ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('تم الحذف')));\n                                        }\n                                      } catch(e) {\n                                        if (context.mounted) {\n                                          ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('خطأ: $e')));\n                                        }\n                                      }\n                                    }\n                                  },\n                                ),\n                              );\n                            },\n                          );\n                        },\n                        loading: () => const Padding(padding: EdgeInsets.all(16.0), child: CircularProgressIndicator()),\n                        error: (e, _) => Text('خطأ: $e'),\n                      );\n                    }\n                  )\n                ],\n              );\n            },\n          );\n        },\n        loading: () => const Center(child: CircularProgressIndicator()),\n        error: (e, _) => Center(child: Text('خطأ: $e')),\n      ),\n    );\n  }\n}\n